# 获取数据包请求方法
get_http_method = func(request_data){
     lines = str.SplitAndTrim(request_data,"\r\n")
    request_line = lines[0]
    method = str.SplitAndTrim(request_line," ")[0]
    return method
}

url1 = cli.String("url1",cli.setHelp("填写url地址则会拼接/auth/gettime获取timestamp,否则使用当前时间戳"),cli.setVerboseName("url地址"))

cli.check()


hijackHTTPRequest = func(isHttps, url, req, forward, drop) {
    time1 = time.Now().Unix()
    # 获取时间2种方式
    if url1 != ""{
    #1.访问{url}/auth/gettime
    rsp, _ = poc.Get(url1+"/auth/gettime")~
    r, _ = re.Compile(`"time":\s*(\d+)`)
    time1 = r.FindStringSubmatch(string(rsp.GetBody()))
    if (len(time1)>1){
        time1 = string(time1[1])
         }
    }
    auth_key_MD5 = codec.Md5(time1)
    method = get_http_method(string(req))
    if method == "GET" {
         _, req = poc.HTTP(req,poc.https(isHttps),poc.appendQueryParam("auth_key",auth_key_MD5),poc.appendQueryParam("timestamp",string(time1)))~
    }
    if method == "POST" {
        _, req = poc.HTTP(req,poc.https(isHttps),poc.appendPostParam("auth_key",auth_key_MD5),poc.appendPostParam("timestamp",string(time1)))~
    }
    forward(req)
}
